function runOrder(tasks: number[][]): number[] {
  const n = tasks.length, done = new Array(n).fill(false), out: number[] = [];
  let now = 0;
  while (out.length < n) {
    let pick = -1, nextArrive = Infinity;
    for (let i = 0; i < n; i++) {
      if (done[i]) continue;
      const [a, len] = tasks[i];
      if (a <= now) { if (pick === -1 || len < tasks[pick][1]) pick = i; }
      else nextArrive = Math.min(nextArrive, a);
    }
    if (pick === -1) { now = nextArrive; continue; }
    done[pick] = true;
    out.push(pick);
    now += tasks[pick][1];
  }
  return out;
}

