class MinHeap {
  private a: [number, number][] = [];
  private less(x: [number, number], y: [number, number]) { return x[0] < y[0] || (x[0] === y[0] && x[1] < y[1]); }
  get size() { return this.a.length; }
  push(v: [number, number]) {
    const a = this.a; a.push(v);
    let i = a.length - 1;
    while (i > 0) { const p = (i - 1) >> 1; if (!this.less(a[i], a[p])) break; [a[i], a[p]] = [a[p], a[i]]; i = p; }
  }
  pop(): [number, number] {
    const a = this.a, top = a[0], last = a.pop()!;
    if (a.length) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < a.length && this.less(a[l], a[m])) m = l;
        if (r < a.length && this.less(a[r], a[m])) m = r;
        if (m === i) break;
        [a[i], a[m]] = [a[m], a[i]]; i = m;
      }
    }
    return top;
  }
}

function runOrder(tasks: number[][]): number[] {
  const n = tasks.length;
  const order = Array.from({ length: n }, (_, i) => i).sort((x, y) => tasks[x][0] - tasks[y][0]);
  const heap = new MinHeap(), out: number[] = [];
  let now = 0, p = 0;
  while (out.length < n) {
    if (heap.size === 0 && now < tasks[order[p]][0]) now = tasks[order[p]][0]; // idle: jump ahead
    while (p < n && tasks[order[p]][0] <= now) { const i = order[p++]; heap.push([tasks[i][1], i]); }
    const [len, i] = heap.pop();
    out.push(i);
    now += len;
  }
  return out;
}

