                now = tasks[order[p]][0]  # idle: jump ahead
            while p < n and tasks[order[p]][0] <= now:
                i = order[p]
                heapq.heappush(heap, (tasks[i][1], i))
                p += 1
            length, i = heapq.heappop(heap)
            out.append(i)
            now += length
        return out

